function emo(str){
  if(!str) return '';
  const re = /(\p{Emoji_Presentation}|\p{Extended_Pictographic})((\u200d(\p{Emoji_Presentation}|\p{Extended_Pictographic}))|\ufe0f|[\u{1F3FB}-\u{1F3FF}])*/gu;
  return str.replace(re, (m)=> EMOJI_SVG[m] ? `<span class="emo-ic">${EMOJI_SVG[m]}</span>` : m);
}

